// TH16 v1.00a Stage 6 BossCard5 (spell 86) — 裏春「エイプリルウィザード」
// Source entry: st06bs.ecl.txt:1411-1487 (BossCard5);
// deps BossCard5_at 1489-1546, BossCard5_at2 1548-1572.
// Source/segment timing: 120-frame shell buffer, then source entry; the 3600-frame
// interrupt window starts 4 frames after the sub starts (timerReset/setInterrupt).

const TIME_LIMIT: int = 3724;      // 120 buffer + 4 entry + 3600 source window
const OPENING_BUFFER: int = 120;

// Approved TH16 aliases (identical TH18 slots); only the two types this card uses.
const TH16_RICE: int = 480;        // source etSprite(0, 8, 4) / at2 uses the same
const TH16_BALL2: int = 432;       // source EX SETSPRITE index4 -> type 5 color 4
const COLOR_FOUR: int = 4;

// Source BossCard5_at EX chain, in order:
//   index2 VELTIME a=120 r=3.0 s=pi/2  -> ramp scalar speed by (3-old)/120 along 90deg
//   index3 BOUNCE   a=1 b=2 (down wall)
//   index4 SETSPRITE a=5 b=0x8004 (type 5, color 4)
//   index5 ACCEL    a=480 r=0.02+RANDF2*0.01 s=pi/2 -> gravity (0, r) for 480 frames
// Birth ANIM (index0), BRIGHT (index1) are omitted per the approved birth-phase policy.
xformdef APRIL_FALL(delta: fx, accel: fx) {
    set_gravity(0fx, delta);
    wait(120);
    bounce_arm(8, 1);              // source U/D/L/R=1/2/4/8 down=2 -> target bit3 down
    set_sprite(TH16_BALL2, COLOR_FOUR);
    set_gravity(0fx, accel);
    wait(480);
    set_gravity(0fx, 0fx);
}

// One at() bullet. Source fires at the absolute offset (x, 0); layers only change speed.
sub card_shot(x: fx, ang: int, spd: fx, accel: fx) {
    var delta: fx = (3fx - spd) / 120fx;
    _ = fire(TH16_RICE, COLOR_FOUR, x, 0fx, spd, ang as angle, APRIL_FALL(delta, accel), none);
}

// BossCard5_at (st06bs.ecl.txt:1489-1546)
// Source rounds/layers/wait: diffI($C,30,50,50,50); etCount layers 1/1/1/2;
// wait [-1] = E16 N8 H6 L6. Per round: right volley then left volley; each volley
// samples RANDF (offset), RANDF2 (angle), RANDF2 (ACCEL r) in that order.
sub card_at() {
    var rounds: int = 50;
    var step_a: int = 1;
    var step_b: int = 3;
    var gap: int = 6;
    var layers: int = 1;
    var rk: int = global(GVAR_RANK);
    if rk == RANK_EASY {
        rounds = 30;
        step_a = 2;
        step_b = 1;
        gap = 16;
    } else if rk == RANK_NORMAL {
        gap = 8;
    } else if rk == RANK_LUNATIC {
        layers = 2;
    }
    var a: int = 184;              // %A
    var b: int = 0;                // %B
    for k in 0..rounds {
        // etOffsetAbs(0, A - RANDF*B, 0); etAngle(0, pi/2 + RANDF2*(pi/9), 0)
        var x1: fx = (a as fx) - (b as fx) * ((rand(16384) as fx) / 16384fx);
        var ang1: int = 16384 + ((rand(32768) - 16384) * 3641) / 16384; // 3641 BAM = 0.349 rad
        var ac1: fx = 0.02fx + ((rand(32768) - 16384) as fx / 16384fx) * 0.01fx;
        card_shot(x1, ang1, 1fx, ac1);
        if layers > 1 {
            card_shot(x1, ang1, 0.2fx, ac1);   // etSpeed(0,1.0,0.2), M=2
        }
        var x2: fx = -(a as fx) + (b as fx) * ((rand(16384) as fx) / 16384fx);
        var ang2: int = 16384 + ((rand(32768) - 16384) * 3641) / 16384;
        var ac2: fx = 0.02fx + ((rand(32768) - 16384) as fx / 16384fx) * 0.01fx;
        card_shot(x2, ang2, 1fx, ac2);
        if layers > 1 {
            card_shot(x2, ang2, 0.2fx, ac2);
        }
        a = a - step_a;            // !E decrements A once more
        if b < 192 {
            b = b + step_b;        // !E step 1, others 3
        }
        wait(gap);
    }
}

// BossCard5_at2 (st06bs.ecl.txt:1548-1572)
// Fixed-direction 10-way fan, spread 0.27925268 rad (16deg), base -pi/2 + RANDF2*0.349,
// speed 5.0, 50 volleys 8 frames apart. etSprite type8 color4; only birth ANIM in EX.
async sub card_at2() {
    sh_reset(0);
    sh_sprite(0, TH16_RICE, COLOR_FOUR);
    sh_aim(0, 0);
    sh_ring(0, 0);
    sh_count(0, 10, 1);
    sh_speed(0, 5fx, 0fx);
    for k in 0..50 {
        var base: int = -16384 + ((rand(32768) - 16384) * 3641) / 16384;
        sh_angle(0, base as angle, 16deg);
        sh_fire(0);
        wait(8);
    }
}

// BossCard5 main body (st06bs.ecl.txt:1411-1487) after the segment hand-off:
// movePosTime(60,4,0,192), +90 -> script time 94, then per iteration
// {at2 async; at; wait200; wait130} twice. Source $D/$I0/%F0 have no consumer in
// this card (loop runs far past the 3600-frame interrupt), so only the loop is kept.
async sub boss_attack() {
    set_invuln(65535);
    set_hurtbox(28fx);             // source setHurtbox(56,56) -> r=28
    set_hitbox(25fx);              // source setHitbox(50,50) -> r=25
    wait(4);                       // source setup/spell declaration at t=4
    move_to(60, 0fx, 192fx, EASE_QUAD_OUT);   // movePosTime(60,4,0,192)
    wait(90);                      // source label +90 -> t=94
    loop {
        spawn card_at2();
        card_at();
        wait(200);
        wait(130);
        spawn card_at2();
        card_at();
        wait(200);
        wait(130);
    }
}

async sub stage_pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, boss_attack);  // boss home y=128 (Boss entry movePos)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, stage_pattern, TIME_LIMIT, 0);
    wait_spell();
    kill_all_enemies(KILL_SILENT);   // card ends (source interrupt): boss leaves, no further fire
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
